"""Dataclass models mirroring the Lumen API schemas."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Literal

ProjectStatus = Literal["active", "archived"]
TaskState = Literal["queued", "in_progress", "done"]
Verdict = Literal["approve", "reject"]
BatchItemStatus = Literal["created", "error"]

_PROJECT_STATUSES = ("active", "archived")
_TASK_STATES = ("queued", "in_progress", "done")
_VERDICTS = ("approve", "reject")


@dataclass(frozen=True, slots=True)
class Error:
    """A structured API error payload."""

    code: str
    message: str
    retryable: bool = False

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> Error:
        return cls(
            code=str(data.get("code", "unknown")),
            message=str(data.get("message", "")),
            retryable=bool(data.get("retryable", False)),
        )


@dataclass(frozen=True, slots=True)
class Project:
    id: str
    name: str
    created_at: str
    status: ProjectStatus
    label_schema: dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if self.status not in _PROJECT_STATUSES:
            raise ValueError(f"invalid project status: {self.status!r}")

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> Project:
        return cls(
            id=data["id"],
            name=data["name"],
            created_at=data["created_at"],
            status=data["status"],
            label_schema=dict(data.get("label_schema") or {}),
        )


@dataclass(frozen=True, slots=True)
class TaskCreate:
    """Payload for creating a task. ``priority`` must be in 1-5 (default 3)."""

    external_id: str
    payload: dict[str, Any] = field(default_factory=dict)
    priority: int = 3

    def __post_init__(self) -> None:
        if not (1 <= self.priority <= 5):
            raise ValueError(f"priority must be between 1 and 5, got {self.priority}")

    def to_dict(self) -> dict[str, Any]:
        return {
            "external_id": self.external_id,
            "payload": dict(self.payload),
            "priority": self.priority,
        }


@dataclass(frozen=True, slots=True)
class Task:
    id: str
    external_id: str
    state: TaskState
    payload: dict[str, Any] = field(default_factory=dict)
    priority: int = 3

    def __post_init__(self) -> None:
        if self.state not in _TASK_STATES:
            raise ValueError(f"invalid task state: {self.state!r}")
        if not (1 <= self.priority <= 5):
            raise ValueError(f"priority must be between 1 and 5, got {self.priority}")

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> Task:
        return cls(
            id=data["id"],
            external_id=data["external_id"],
            state=data["state"],
            payload=dict(data.get("payload") or {}),
            priority=int(data.get("priority", 3)),
        )


@dataclass(frozen=True, slots=True)
class Annotation:
    id: str
    task_id: str
    labels: dict[str, Any]
    annotator: str
    confidence: float

    def __post_init__(self) -> None:
        if not (0.0 <= self.confidence <= 1.0):
            raise ValueError(f"confidence must be in [0, 1], got {self.confidence}")

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> Annotation:
        return cls(
            id=data["id"],
            task_id=data["task_id"],
            labels=dict(data.get("labels") or {}),
            annotator=data["annotator"],
            confidence=float(data["confidence"]),
        )


@dataclass(frozen=True, slots=True)
class BatchItemResult:
    """One per-item result from a batch-create call.

    ``index`` is the position of the item in the *original* sequence passed to
    ``batch_create``, even when the call was split into multiple chunks.
    """

    index: int
    status: BatchItemStatus
    task: Task | None = None
    error: Error | None = None

    @classmethod
    def from_dict(cls, data: dict[str, Any], *, index_offset: int = 0) -> BatchItemResult:
        task_data = data.get("task")
        error_data = data.get("error")
        return cls(
            index=int(data["index"]) + index_offset,
            status=data["status"],
            task=Task.from_dict(task_data) if task_data else None,
            error=Error.from_dict(error_data) if error_data else None,
        )


