class AnnotationsResource:
    def __init__(self, client: LumenClient) -> None:
        self._client = client

    def review(
        self, annotation_id: str, verdict: Verdict, *, note: str | None = None
    ) -> ReviewResult:
        """Review an annotation.

        Re-submitting the same verdict is idempotent and returns a result with
        ``already_applied=True``; a conflicting verdict raises
        :class:`~lumen.exceptions.ConflictError`.
        """
        if verdict not in ("approve", "reject"):
            raise ValueError(f"verdict must be 'approve' or 'reject', got {verdict!r}")
        response = self._client._request(
            "POST",
            f"/annotations/{annotation_id}:review",
            json_body={"verdict": verdict, "note": note},
        )
        body = response.json()
        body.setdefault("annotation_id", annotation_id)
        return ReviewResult.from_dict(body)

"""In-process mock of the Lumen Annotation API.

Implements the API contract over ``httpx.MockTransport`` so the client and
its test suite run fully offline:

    server = MockLumenServer()
    client = LumenClient("test-key", transport=server.transport())

State (projects, tasks, annotations, reviews) lives in memory. Helper
methods seed data, expire cursors, and enqueue scripted failure responses
(429 / 5xx) that are returned ahead of normal routing.
"""

from __future__ import annotations

import json
import re
from typing import Any

import httpx

DEFAULT_LIMIT = 50
MAX_LIMIT = 200

_PROJECT_RE = re.compile(r"^/v1/projects/(?P<id>[^/:]+)$")
_BATCH_RE = re.compile(r"^/v1/projects/(?P<id>[^/:]+)/tasks:batchCreate$")
_ANNOTATIONS_RE = re.compile(r"^/v1/tasks/(?P<id>[^/:]+)/annotations$")
_REVIEW_RE = re.compile(r"^/v1/annotations/(?P<id>[^/:]+):review$")


def _error_response(
    status: int,
    code: str,
    message: str,
    *,
    retryable: bool = False,
    headers: dict[str, str] | None = None,
) -> httpx.Response:
    body = {"error": {"code": code, "message": message, "retryable": retryable}}
    return httpx.Response(status, json=body, headers=headers)


class MockLumenServer:
    """Stateful, contract-driven mock of the Lumen API."""

    def __init__(self, *, api_key: str | None = None) -> None:
        self.api_key = api_key
        self.projects: dict[str, dict[str, Any]] = {}
        self.tasks: dict[str, dict[str, Any]] = {}
        self.annotations: dict[str, list[dict[str, Any]]] = {}
        self.reviews: dict[str, str] = {}
        self.requests: list[httpx.Request] = []
        self.failing_external_ids: set[str] = set()
        self._scripted: list[httpx.Response] = []
        self._cursors: dict[str, tuple[str, int]] = {}
        self._stale_cursors: set[str] = set()
        self._next_id = 0

    # -- wiring --------------------------------------------------------------

    def transport(self) -> httpx.MockTransport:
        return httpx.MockTransport(self.handle)

    # -- seeding & scripting helpers ------------------------------------------

    def add_project(
        self,
        project_id: str,
        name: str | None = None,
        *,
        status: str = "active",
        created_at: str = "2026-01-01T00:00:00Z",
        label_schema: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        project = {
            "id": project_id,
            "name": name or project_id,
            "created_at": created_at,
            "status": status,
            "label_schema": label_schema or {},
        }
        self.projects[project_id] = project
        return project

    def add_annotation(
        self,
        annotation_id: str,
        task_id: str,
        *,
        labels: dict[str, Any] | None = None,
        annotator: str = "ann-1",
        confidence: float = 0.9,
    ) -> dict[str, Any]:
        annotation = {
            "id": annotation_id,
            "task_id": task_id,
            "labels": labels or {},
            "annotator": annotator,
            "confidence": confidence,
        }
        self.annotations.setdefault(task_id, []).append(annotation)
        return annotation

    def enqueue_response(self, response: httpx.Response) -> None:
        """Script a response returned verbatim for the next request."""
        self._scripted.append(response)

    def expire_cursors(self) -> None:
        """Mark every cursor issued so far as stale (subsequent use -> 410)."""
        self._stale_cursors.update(self._cursors)

    # -- request handling ------------------------------------------------------

    def handle(self, request: httpx.Request) -> httpx.Response:
        self.requests.append(request)
        if self._scripted:
            return self._scripted.pop(0)
        if self.api_key is not None and request.headers.get("X-Lumen-Key") != self.api_key:
            return _error_response(401, "unauthorized", "invalid API key")

        path = request.url.path
        if request.method == "GET" and path == "/v1/projects":
            return self._list(request, "projects", list(self.projects.values()))
        if request.method == "GET" and (m := _PROJECT_RE.match(path)):
            return self._get_project(m.group("id"))
        if request.method == "POST" and (m := _BATCH_RE.match(path)):
            return self._batch_create(m.group("id"), request)
        if request.method == "GET" and (m := _ANNOTATIONS_RE.match(path)):
            task_id = m.group("id")
            items = list(self.annotations.get(task_id, []))
            return self._list(request, f"annotations:{task_id}", items)
        if request.method == "POST" and (m := _REVIEW_RE.match(path)):
            return self._review(m.group("id"), request)
        return _error_response(404, "not_found", f"no route for {request.method} {path}")

    # -- endpoint implementations ------------------------------------------------

    def _list(
        self, request: httpx.Request, collection: str, items: list[dict[str, Any]]
    ) -> httpx.Response:
        params = request.url.params
        try:
            limit = int(params.get("limit", DEFAULT_LIMIT))
        except ValueError:
            return _error_response(400, "invalid_request", "limit must be an integer")
        if not (1 <= limit <= MAX_LIMIT):
            return _error_response(400, "invalid_request", f"limit must be 1-{MAX_LIMIT}")

        offset = 0
        cursor = params.get("cursor")
        if cursor is not None:
            if cursor in self._stale_cursors or cursor not in self._cursors:
                return _error_response(410, "stale_cursor", "cursor has expired")
            cursor_collection, offset = self._cursors[cursor]
            if cursor_collection != collection:
                return _error_response(400, "invalid_request", "cursor/collection mismatch")

        page = items[offset : offset + limit]
        next_cursor: str | None = None
        if offset + limit < len(items):
            next_cursor = f"cur_{len(self._cursors)}"
            self._cursors[next_cursor] = (collection, offset + limit)
        return httpx.Response(200, json={"items": page, "next_cursor": next_cursor})

    def _get_project(self, project_id: str) -> httpx.Response:
        project = self.projects.get(project_id)
        if project is None:
            return _error_response(404, "not_found", f"project {project_id} not found")
        return httpx.Response(200, json=project)

    def _batch_create(self, project_id: str, request: httpx.Request) -> httpx.Response:
        if project_id not in self.projects:
            return _error_response(404, "not_found", f"project {project_id} not found")
        try:
            body = json.loads(request.content)
        except json.JSONDecodeError:
            return _error_response(400, "invalid_request", "body must be JSON")
        tasks = body.get("tasks")
        if not isinstance(tasks, list):
            return _error_response(400, "invalid_request", "'tasks' must be a list")
        if len(tasks) > 100:
            return _error_response(400, "invalid_request", "at most 100 tasks per call")

        results: list[dict[str, Any]] = []
        for index, spec in enumerate(tasks):
            external_id = spec.get("external_id", "")
            if external_id in self.failing_external_ids:
                results.append(
                    {
                        "index": index,
                        "status": "error",
                        "task": None,
                        "error": {
                            "code": "duplicate_external_id",
                            "message": f"external_id {external_id!r} already exists",
                            "retryable": False,
                        },
                    }
                )
                continue
            self._next_id += 1
            task = {
                "id": f"task_{self._next_id}",
                "external_id": external_id,
                "payload": spec.get("payload", {}),
                "priority": spec.get("priority", 3),
                "state": "queued",
            }
            self.tasks[task["id"]] = task
            results.append({"index": index, "status": "created", "task": task, "error": None})
        return httpx.Response(207, json={"results": results})

    def _review(self, annotation_id: str, request: httpx.Request) -> httpx.Response:
        known = {a["id"] for anns in self.annotations.values() for a in anns}
        if annotation_id not in known:
            return _error_response(404, "not_found", f"annotation {annotation_id} not found")
        try:
            body = json.loads(request.content)
        except json.JSONDecodeError:
            return _error_response(400, "invalid_request", "body must be JSON")
        verdict = body.get("verdict")
        if verdict not in ("approve", "reject"):
            return _error_response(400, "invalid_request", "verdict must be approve|reject")

        existing = self.reviews.get(annotation_id)
        if existing is None:
            self.reviews[annotation_id] = verdict
            return httpx.Response(
                200,
                json={
                    "annotation_id": annotation_id,
                    "verdict": verdict,
                    "already_applied": False,
                },
            )
        if existing == verdict:
            return httpx.Response(
                200,
                json={
                    "annotation_id": annotation_id,
                    "verdict": verdict,
                    "already_applied": True,
                },
            )
        return _error_response(
            409, "conflict", f"annotation already reviewed with verdict {existing!r}"
        )

"""Typed exceptions raised by the Lumen client."""

from __future__ import annotations

from .models import Error


class LumenAPIError(Exception):
    """Base class for all API-level errors.

    Carries the HTTP ``status_code`` and, when the server returned a
    structured error body, the parsed :class:`~lumen.models.Error`.
    """

    def __init__(self, message: str, *, status_code: int, error: Error | None = None) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.error = error

    def __repr__(self) -> str:
        return (
            f"{type(self).__name__}(status_code={self.status_code}, "
            f"error={self.error!r}, message={str(self)!r})"
        )


class NotFoundError(LumenAPIError):
    """The requested resource does not exist (HTTP 404)."""


class RateLimitError(LumenAPIError):
    """Rate limit exceeded and retries were exhausted (HTTP 429)."""

    def __init__(
        self,
        message: str,
        *,
        status_code: int = 429,
        error: Error | None = None,
        retry_after: float | None = None,
    ) -> None:
        super().__init__(message, status_code=status_code, error=error)
        self.retry_after = retry_after


class ConflictError(LumenAPIError):
    """The request conflicts with current resource state (HTTP 409)."""


class StaleCursorError(LumenAPIError):
    """A pagination cursor has expired (HTTP 410)."""

from __future__ import annotations

import random

import pytest

from lumen import LumenClient
from lumen.testing import MockLumenServer


class RecordingSleep:
    """Stand-in for time.sleep that records requested durations."""

    def __init__(self) -> None:
        self.calls: list[float] = []

    def __call__(self, seconds: float) -> None:
        self.calls.append(seconds)


class ZeroJitter(random.Random):
    """RNG whose uniform() always returns the lower bound (no jitter)."""

    def uniform(self, a: float, b: float) -> float:
        return a


class FixedJitter(random.Random):
    """RNG whose uniform() always returns a fixed value."""

    def __init__(self, value: float) -> None:
        super().__init__(0)
        self.value = value

    def uniform(self, a: float, b: float) -> float:
        return self.value


